import React, { useState, useEffect } from 'react';
import { aiAPI } from '../services/api';

/**
 * Dashboard Page
 * Shows AI-powered insights and analytics
 */
function Dashboard() {
  const [insights, setInsights] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetchInsights();
  }, []);

  const fetchInsights = async () => {
    try {
      setLoading(true);
      const response = await aiAPI.getInsights();
      setInsights(response.data.data);
      setError(null);
    } catch (err) {
      setError('Failed to load insights');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  if (loading) return <div className="loading">Loading insights</div>;
  if (error) return <div className="error">{error}</div>;
  if (!insights) return null;

  return (
    <div className="container">
      <h1 style={{ marginBottom: '2rem', color: '#667eea' }}>
        📊 AI-Powered Insights Dashboard
      </h1>

      {/* Summary Statistics */}
      <div className="stats-grid">
        <div className="stat-card">
          <h3>Total Products</h3>
          <div className="value">{insights.summary.totalProducts}</div>
        </div>
        <div className="stat-card">
          <h3>Total Stores</h3>
          <div className="value">{insights.summary.totalStores}</div>
        </div>
        <div className="stat-card">
          <h3>Inventory Value</h3>
          <div className="value">${insights.summary.totalInventoryValue}</div>
        </div>
        <div className="stat-card">
          <h3>Low Stock Alerts</h3>
          <div className="value">{insights.summary.lowStockCount}</div>
        </div>
      </div>

      <div className="grid-2">
        {/* Top Selling Products */}
        <div className="card">
          <h2>🏆 Top Selling Products</h2>
          {insights.topSelling.length > 0 ? (
            <div className="table-container">
              <table>
                <thead>
                  <tr>
                    <th>Product</th>
                    <th>Category</th>
                    <th>Sales</th>
                    <th>Revenue</th>
                  </tr>
                </thead>
                <tbody>
                  {insights.topSelling.map((item, index) => (
                    <tr key={index}>
                      <td>{item.productName}</td>
                      <td>
                        <span className="badge badge-success">
                          {item.category}
                        </span>
                      </td>
                      <td>{item.totalSales} units</td>
                      <td>${item.revenue}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <p>No sales data available</p>
          )}
        </div>

        {/* Low Stock Alerts */}
        <div className="card">
          <h2>⚠️ Low Stock Alerts</h2>
          {insights.lowStockAlerts.length > 0 ? (
            <div className="table-container">
              <table>
                <thead>
                  <tr>
                    <th>Product</th>
                    <th>Store</th>
                    <th>Stock</th>
                    <th>Reorder Point</th>
                  </tr>
                </thead>
                <tbody>
                  {insights.lowStockAlerts.map((item, index) => (
                    <tr key={index}>
                      <td>{item.productName}</td>
                      <td>{item.storeName}</td>
                      <td>
                        <span className="badge badge-danger">
                          {item.currentStock}
                        </span>
                      </td>
                      <td>{item.reorderPoint}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <p style={{ color: '#28a745' }}>✓ All products are well stocked!</p>
          )}
        </div>
      </div>

      <div className="grid-2">
        {/* Slow Moving Inventory */}
        <div className="card">
          <h2>🐌 Slow Moving Inventory</h2>
          {insights.slowMoving.length > 0 ? (
            <div className="table-container">
              <table>
                <thead>
                  <tr>
                    <th>Product</th>
                    <th>Store</th>
                    <th>Quantity</th>
                    <th>Days of Stock</th>
                  </tr>
                </thead>
                <tbody>
                  {insights.slowMoving.map((item, index) => (
                    <tr key={index}>
                      <td>{item.productName}</td>
                      <td>{item.storeName}</td>
                      <td>{item.quantity}</td>
                      <td>
                        <span className="badge badge-warning">
                          {item.daysOfStock} days
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <p>No slow-moving inventory detected</p>
          )}
        </div>

        {/* Stock Redistribution Suggestions */}
        <div className="card">
          <h2>🔄 Suggested Stock Transfers</h2>
          {insights.imbalances.length > 0 ? (
            <div>
              {insights.imbalances.map((item, index) => (
                <div
                  key={index}
                  style={{
                    padding: '1rem',
                    background: '#f8f9fa',
                    borderRadius: '8px',
                    marginBottom: '1rem'
                  }}
                >
                  <h4 style={{ marginBottom: '0.5rem', color: '#667eea' }}>
                    {item.productName}
                  </h4>
                  <p style={{ fontSize: '0.9rem', marginBottom: '0.5rem' }}>
                    Transfer <strong>{item.quantity} units</strong>
                  </p>
                  <p style={{ fontSize: '0.85rem', color: '#666' }}>
                    From: <strong>{item.fromStoreName}</strong> →
                    To: <strong>{item.toStoreName}</strong>
                  </p>
                  <p style={{ fontSize: '0.8rem', color: '#999', marginTop: '0.5rem' }}>
                    {item.reason}
                  </p>
                </div>
              ))}
            </div>
          ) : (
            <p style={{ color: '#28a745' }}>
              ✓ Stock is well balanced across stores!
            </p>
          )}
        </div>
      </div>

      <button
        onClick={fetchInsights}
        className="btn btn-primary"
        style={{ marginTop: '1rem' }}
      >
        🔄 Refresh Insights
      </button>
    </div>
  );
}

export default Dashboard;

